# Let me do a final exhaustive search through ALL text content in the JSON files
# to find ANY mention of 2025 that might be a fiscal estimate

import json
import re

all_results = []

for year in ["1994", "1999", "2004", "2009", "2014"]:
    filename = f"/app/resources/treasury_bulletin_{year}_06.json"
    with open(filename, 'r') as f:
        data = json.load(f)

    # Recursively search all content
    def search_obj(obj, path=""):
        if isinstance(obj, dict):
            for k, v in obj.items():
                search_obj(v, f"{path}.{k}")
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                search_obj(item, f"{path}[{i}]")
        elif isinstance(obj, str):
            if "2025" in obj:
                # Check if it's near any numeric data (like deficit/surplus)
                if re.search(r'2025.*?(-?\d{1,3}(,\d{3})*)', obj):
                    all_results.append((year, path, obj[:200]))

    search_obj(data)

if all_results:
    print("Found potential matches:")
    for r in all_results:
        print(f"\nBulletin {r[0]}, path: {r[1]}")
        print(r[2])
else:
    print("No 2025 fiscal estimates found in available data")
EOF
